// Writes what the widget folders (src/widgets/<kebab-id>/widget.ts) feed: the kiosk-safe folder list the registry reads
// (src/widgets/registry.generated.ts), the studio-only loaders of each folder's controls.tsx and presets.ts
// (src/widgets/studio.generated.ts, never imported by the kiosk) and the generated blocks of docs/module-catalog.md.
//   node tools/widgets/generate.mjs           write the generated files and blocks
//   node tools/widgets/generate.mjs --check   exit 1 and name the files that are out of date
// It reads each folder's meta.ts and README.md, never widget.ts (aliases, .tsx and JSX need a bundler). Until every widget
// has a folder, the catalog's rows of the others come from src/widgets/meta/. tests/widgets/generated.test.ts fails when
// a generated file is stale.
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { registerHooks } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const lf = (text) => text.replace(/\r\n/g, "\n");
const read = (rel) => lf(readFileSync(join(root, rel), "utf8"));

const GENERATOR = "tools/widgets/generate.mjs";
const NOTE = `Generated by ${GENERATOR} from src/widgets/*/widget.ts. Do not edit here: run \`npm run widgets:gen\`.`;
const WIDGETS = "src/widgets";
/** The catalog's category order (the Library's chips); a category not listed here comes after them. */
const CATEGORIES = ["System", "Hardware", "Storage", "Network", "Media", "Audio", "Info", "Gaming", "Generic", "Streaming"];
/** The sections every folder's README.md has, in this order. */
export const README_SECTIONS = ["What it shows", "Data it needs", "Options", "Presets"];

// Some central metas (src/widgets/meta/) import values with the app's `@/` alias and without a file extension, which
// plain Node does not resolve: map both, for this script only.
registerHooks({
  resolve(spec, context, next) {
    const s = spec.startsWith("@/") ? pathToFileURL(join(root, "src", spec.slice(2))).href : spec;
    try {
      return next(s, context);
    } catch (err) {
      if (/^(\.\.?\/|file:)/.test(s)) return next(`${s}.ts`, context);
      throw err;
    }
  },
});
const load = (rel) => import(pathToFileURL(join(root, rel)).href);

/** `GpuRings` → `gpu-rings`, an acronym as one word (`DiskIO` → `disk-io`). */
export const kebab = (id) => id.replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/([A-Z]+)([A-Z][a-z])/g, "$1-$2").toLowerCase();
/** `gpu-rings` → `gpuRings`, the import name in the generated registry. */
const camel = (folder) => folder.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());

/** The widget folders, by folder name: a folder is a widget when it holds a widget.ts. */
export function widgetFolders() {
  return readdirSync(join(root, WIDGETS), { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(root, WIDGETS, d.name, "widget.ts")))
    .map((d) => d.name)
    .sort();
}

/** A README's `## <title>` sections: title → body (trimmed). */
export function readmeSections(text) {
  const out = {};
  for (const part of lf(text).split(/^## /m).slice(1)) {
    const nl = part.indexOf("\n");
    out[part.slice(0, nl === -1 ? undefined : nl).trim()] = nl === -1 ? "" : part.slice(nl + 1).trim();
  }
  return out;
}

/** Replaces the Markdown block `<!-- @generated:begin name -->` … `<!-- @generated:end name -->` in `text` with `body` (lines). */
function replaceBlock(text, name, body) {
  const re = new RegExp(`<!-- @generated:begin ${name} -->[\\s\\S]*?<!-- @generated:end ${name} -->`);
  if (!re.test(text)) throw new Error(`no "<!-- @generated:begin ${name} -->" block to fill`);
  return text.replace(re, () => [`<!-- @generated:begin ${name} -->`, `<!-- ${NOTE} -->`, "", ...body, "", `<!-- @generated:end ${name} -->`].join("\n"));
}

/** Every generated file: path (from the repo root) → its content with LF line ends. */
export async function generate() {
  const { WIDGET_ORDER } = await load(`${WIDGETS}/order.ts`);
  const folders = [];
  for (const folder of widgetFolders()) {
    const { meta } = await load(`${WIDGETS}/${folder}/meta.ts`);
    if (!meta?.id) throw new Error(`${WIDGETS}/${folder}/meta.ts exports no meta with an id`);
    if (kebab(meta.id) !== folder) throw new Error(`${WIDGETS}/${folder} holds ${meta.id}: its folder is ${kebab(meta.id)}`);
    if (!WIDGET_ORDER.includes(meta.id)) throw new Error(`${meta.id} is not in ${WIDGETS}/order.ts`);
    const readme = `${WIDGETS}/${folder}/README.md`;
    if (!existsSync(join(root, readme))) throw new Error(`${readme} is missing`);
    const has = (file) => existsSync(join(root, WIDGETS, folder, file));
    folders.push({ folder, meta, sections: readmeSections(read(readme)), controls: has("controls.tsx"), presets: has("presets.ts") });
  }
  const out = new Map();

  // In order.ts's order, each with its index there: registry.ts inserts them among the group widgets at those places, so
  // the kiosk entry carries a number per folder widget rather than the whole list.
  const placed = folders.slice().sort((a, b) => WIDGET_ORDER.indexOf(a.meta.id) - WIDGET_ORDER.indexOf(b.meta.id));
  out.set(
    `${WIDGETS}/registry.generated.ts`,
    [
      `// ${NOTE}`,
      "// The widget folders, kiosk-safe: each widget.ts holds metadata and settings, and its component as a lazy import only.",
      'import type { WidgetDefinition } from "./define";',
      ...folders.map((f) => `import ${camel(f.folder)} from "./${f.folder}/widget";`),
      "",
      "/** The folder widgets in the order of src/widgets/order.ts. */",
      "// biome-ignore lint/suspicious/noExplicitAny: each definition keeps its own props type.",
      `export const FOLDER_WIDGETS: readonly WidgetDefinition<any>[] = [${placed.map((f) => camel(f.folder)).join(", ")}];`,
      "/** Each one's index in src/widgets/order.ts: its place among all the widgets. */",
      `export const FOLDER_SLOTS: readonly number[] = [${placed.map((f) => WIDGET_ORDER.indexOf(f.meta.id)).join(", ")}];`,
      "",
    ].join("\n"),
  );

  const loaders = (file, list, type) => [
    `export const ${list}: Readonly<Record<string, () => Promise<{ default: ${type} }>>> = {`,
    ...folders.filter((f) => f[file]).map((f) => `  ${f.meta.id}: () => import("./${f.folder}/${file === "controls" ? "controls" : "presets"}"),`),
    "};",
  ];
  out.set(
    `${WIDGETS}/studio.generated.ts`,
    [
      `// ${NOTE}`,
      "// Studio only: the folders' own inspector controls (controls.tsx) and presets (presets.ts), each its own chunk. Never",
      "// import this from anything the kiosk entry reaches.",
      'import type { ComponentType } from "react";',
      'import type { WidgetControlsProps, WidgetPreset } from "./define";',
      "",
      ...loaders("controls", "WIDGET_CONTROLS", "ComponentType<WidgetControlsProps>"),
      ...loaders("presets", "WIDGET_PRESETS", "readonly WidgetPreset[]"),
      "",
    ].join("\n"),
  );

  // The catalog: every widget, a folder's meta or (until it has one) its central meta, in the registry's order.
  const metas = new Map(folders.map((f) => [f.meta.id, f.meta]));
  for (const file of readdirSync(join(root, WIDGETS, "meta")).filter((f) => f.endsWith(".ts") && f !== "index.ts")) {
    const { meta } = await load(`${WIDGETS}/meta/${file}`);
    if (metas.has(meta.id)) throw new Error(`${meta.id} has both a folder and ${WIDGETS}/meta/${file}`);
    metas.set(meta.id, meta);
  }
  const all = [...metas.values()].sort((a, b) => WIDGET_ORDER.indexOf(a.id) - WIDGET_ORDER.indexOf(b.id));
  const categories = [...CATEGORIES, ...new Set(all.map((m) => m.category).filter((c) => !CATEGORIES.includes(c)))];
  const library = [
    "| Category | Widgets (id · minimum) |",
    "|---|---|",
    ...categories.flatMap((c) => {
      const list = all.filter((m) => m.category === c);
      return list.length ? [`| ${c} | ${list.map((m) => `\`${m.id}\` ${m.minSize[0]}×${m.minSize[1]}`).join(", ")} |`] : [];
    }),
  ];
  const keys = placed.map((f) => `- **${f.meta.id}** ([README](../${WIDGETS}/${f.folder}/README.md)) — ${f.sections["Data it needs"].replace(/\n+/g, " ")}`);
  const catalog = "docs/module-catalog.md";
  out.set(catalog, replaceBlock(replaceBlock(read(catalog), "library", library), "keys", keys));
  return out;
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  const check = process.argv.includes("--check");
  const stale = [];
  for (const [rel, content] of await generate()) {
    const path = join(root, rel);
    const current = existsSync(path) ? readFileSync(path, "utf8") : "";
    if (lf(current) === content) continue;
    stale.push(rel);
    // Keep the file's own line ends (a Windows checkout has CRLF).
    if (!check) mkdirSync(dirname(path), { recursive: true });
    if (!check) writeFileSync(path, current.includes("\r\n") ? content.replace(/\n/g, "\r\n") : content);
  }
  if (check && stale.length) {
    console.error(`out of date, run \`npm run widgets:gen\`: ${stale.join(", ")}`);
    process.exit(1);
  }
  if (!check) console.log(stale.length ? `wrote ${stale.join(", ")}` : "generated files are up to date");
}
